"""Magias de nível 5. Tradução não oficial do SRD 5.2.1."""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from spell_hl import D, H, T, X

SPELL = {
 "animate_objects": "Objetos não mágicos no alcance, soltos, não vestidos nem carregados e não Colossais, ganham vida: até seu modificador de conjuração em objetos (Médio ou menor conta 1, Grande 2, Enorme 3). Cada um vira um Constructo (Objeto Animado) sob seu controle até a magia acabar ou cair a 0 PV; é aliado e age logo após você.\n\nComo Ação Bônus, comande mentalmente os que estiverem a até 150 m (a mesma ordem para todos). Sem ordens, usam Esquivar. A 0 PV, voltam a ser objetos e o dano restante passa ao objeto." + X("O dano da Pancada aumenta em 1d4 (Médio ou menor), 1d6 (Grande) ou 1d12 (Enorme) por nível de espaço acima de 5."),
 "antilife_shell": "Uma aura numa Emanação de 3 m te acompanha pela duração e impede criaturas (exceto Constructos e Mortos-Vivos) de atravessá-la ou alcançar através dela; elas ainda podem conjurar magias e atacar à distância ou com armas de Alcance. Se você se mover forçando uma delas a atravessar a barreira, a magia termina.",
 "arcane_hand": "Você cria uma mão Grande de energia cintilante num espaço que você vê no alcance pela duração: objeto com CA 20 e PV iguais aos seus PV máximos (a 0, a magia termina); não ocupa o espaço. Ao conjurar e como Ação Bônus depois, mova-a até 18 m e escolha:\n\nPunho Cerrado. Ataque mágico corpo a corpo contra alvo a até 1,5 m: 5d8 de dano de Energia.\nMão Poderosa. Criatura Enorme ou menor a até 1,5 m faz salvaguarda de Força ou é empurrada 1,5 m + 5 × seu modificador de conjuração (em pés; ~1,5 m por ponto).\nMão Agarradora. Criatura Enorme ou menor a até 1,5 m faz salvaguarda de Destreza ou fica Agarrada (CD de fuga = sua CD de magia); como Ação Bônus, esmague-a: 4d6 + modificador de conjuração de dano Contundente.\nMão Interposta. Você tem Meia Cobertura contra efeitos vindos do espaço dela ou que passem por ele, que é Terreno Difícil para inimigos." + X("O Punho Cerrado causa +2d8 e a Mão Agarradora +2d6 por nível de espaço acima de 5."),
 "awaken": "Você traça caminhos mágicos numa gema preciosa e toca o alvo: uma Fera ou criatura Planta com Inteligência 3 ou menor, ou uma planta natural. Ele ganha Inteligência 10 e fala um idioma que você conhece; uma planta vira criatura Planta, move galhos e raízes e ganha sentidos como os humanos (o Mestre escolhe as estatísticas, como Arbusto ou Árvore Desperta). Fica Enfeitiçado por 30 dias ou até ser ferido por você ou aliados; depois, escolhe sua atitude com você.",
 "cloudkill": "Uma Esfera de 6 m de raio de névoa verde-amarelada surge num ponto no alcance, Densamente Obscurecida, pela duração ou até um vento forte dispersá-la. Cada criatura nela faz salvaguarda de Constituição: 5d8 de dano de Veneno na falha, metade no sucesso; também quando a Esfera chega a ela, entra ou termina o turno nela (uma vez por turno). A Esfera se afasta 3 m de você no começo de cada turno seu." + D("1d8", 5),
 "commune": "Você contata uma divindade ou representante divino e faz até três perguntas de sim ou não antes de a magia acabar, recebendo respostas corretas. Seres divinos não são oniscientes: a resposta pode ser \"incerto\", ou uma frase curta se uma palavra enganaria. Cada conjuração extra antes de um Descanso Longo tem 25% cumulativos de chance de não ter resposta.",
 "commune_with_nature": "Você comunga com espíritos da natureza e conhece a área num raio de 5 km ao ar livre (90 m em cavernas naturais); não funciona em construções e povoados. Escolha três fatos sobre a área: povoados; portais para outros planos; um Celestial, Elemental, Fada, Corruptor ou Morto-Vivo de ND 10+ (escolha do Mestre); a planta, mineral ou Fera mais comum; corpos d'água.",
 "cone_of_cold": "Uma rajada de ar gelado sai de você. Cada criatura num Cone de 18 m faz salvaguarda de Constituição: 8d8 de dano de Frio na falha, metade no sucesso. Quem morrer vira uma estátua congelada até descongelar." + D("1d8", 5),
 "conjure_elemental": "Você conjura um espírito elemental Grande e intangível num espaço no alcance pela duração; o elemento define o dano: ar (Elétrico), terra (Trovejante), fogo (Fogo) ou água (Frio). Quando uma criatura que você vê entra no espaço dele ou começa o turno a até 1,5 m, e ele não estiver segurando ninguém, você pode forçar uma salvaguarda de Destreza: na falha, 8d8 de dano do tipo e fica Impedida até a magia acabar. No começo de cada turno, a Impedida repete: na falha sofre 4d8; no sucesso, se solta." + D("1d8", 5),
 "contact_other_plane": "Você contata mentalmente um semideus, o espírito de um sábio morto ou outra entidade de outro plano. Faça uma salvaguarda de Inteligência CD 15. No sucesso, faça até cinco perguntas antes do fim; o Mestre responde com uma palavra (\"sim\", \"não\", \"talvez\", \"nunca\", \"irrelevante\", \"incerto\") ou uma frase curta se uma palavra enganaria. Na falha, você sofre 6d6 de dano Psíquico e fica Incapacitado até um Descanso Longo (Restauração Maior encerra).",
 "contagion": "Seu toque transmite um contágio mágico. O alvo faz salvaguarda de Constituição ou sofre 11d8 de dano Necrótico e fica Envenenado, com Desvantagem nas salvaguardas de um atributo que você escolhe. Repete no fim de cada turno até somar três sucessos (a magia termina) ou três falhas (dura 7 dias). Efeitos que encerrariam o Envenenado exigem antes uma salvaguarda de Constituição bem-sucedida.",
 "creation": "Você puxa material sombrio do Pendor das Sombras e cria um objeto vegetal (tecido, corda, madeira) ou mineral (pedra, cristal, metal) que já viu, de até um Cubo de 1,5 m no alcance. A duração depende do material: vegetal 24 horas; pedra ou cristal 12 horas; metais preciosos 1 hora; gemas 10 minutos; adamante ou mitral 1 minuto (com vários materiais, vale a menor). Usado como componente material de outra magia, faz ela falhar." + X("O Cubo aumenta em 1,5 m por nível de espaço acima de 5."),
 "dispel_evil_and_good": "Pela duração, Celestiais, Elementais, Fadas, Corruptores e Mortos-Vivos têm Desvantagem nos ataques contra você. Você pode encerrar a magia antes com:\n\nQuebrar Encantamento. Ação Magia: toque uma criatura possuída, Enfeitiçada ou Amedrontada por esses tipos; ela se liberta.\nBanir. Ação Magia: uma criatura desses tipos a até 1,5 m faz salvaguarda de Carisma ou volta ao plano natal (Mortos-Vivos ao Pendor das Sombras, Fadas à Agrestia das Fadas).",
 "dominate_person": "Um Humanoide que você vê no alcance faz salvaguarda de Sabedoria (com Vantagem se estiverem lutando com ele) ou fica Enfeitiçado pela duração, repetindo sempre que sofrer dano. Por um elo telepático, você dá ordens sem ação e ele obedece no turno dele; sem ordens, protege-se. Para ele usar uma Reação, você gasta a sua." + X("A Concentração dura mais: até 10 minutos com espaço de nível 6, 1 hora com 7 e 8 horas com 8+."),
 "dream": "Escolha uma criatura que você conhece no mesmo plano. Você ou uma criatura voluntária que toca entra em transe como mensageiro (Incapacitado, Deslocamento 0). Se o alvo dormir, o mensageiro aparece no sonho, conversa e molda o cenário enquanto ele dormir; o alvo lembra de tudo ao acordar. Se estiver acordado, o mensageiro pode encerrar ou esperar. O mensageiro pode ser aterrorizante: entrega até dez palavras e o alvo faz salvaguarda de Sabedoria; na falha, não descansa e sofre 3d6 de dano Psíquico ao acordar.",
 "flame_strike": "Uma coluna vertical de fogo desce do alto. Cada criatura num Cilindro de 3 m de raio e 12 m de altura num ponto no alcance faz salvaguarda de Destreza: 5d6 de dano de Fogo e 5d6 Radiante na falha, metade no sucesso." + D("1d6", 5, "O dano de Fogo e o Radiante (cada)"),
 "geas": "Você dá uma ordem verbal a uma criatura que vê no alcance: cumprir um serviço ou evitar uma ação. Ela faz salvaguarda de Sabedoria (passa se não entender) ou fica Enfeitiçada pela duração; agir diretamente contra a ordem causa 5d10 de dano Psíquico, no máximo uma vez por dia. Ordens suicidas encerram a magia. Remover Maldição, Restauração Maior ou Desejo encerram." + X("Com espaço de nível 7 ou 8, dura 365 dias; com nível 9, até ser encerrada por uma dessas magias."),
 "greater_restoration": "Você toca uma criatura e remove um efeito: 1 nível de Exaustão; Enfeitiçado ou Petrificado; uma maldição (inclusive Sintonia com item amaldiçoado); redução de um valor de atributo; ou redução dos PV máximos.",
 "hallow": "Você toca um ponto e impregna uma área de até 18 m de raio com poder sagrado ou profano (falha se sobrepor outro Consagrar).\n\nProteção Consagrada. Escolha tipos (Aberração, Celestial, Elemental, Fada, Corruptor, Morto-Vivo): não entram voluntariamente, e quem estiver possuído, Enfeitiçado ou Amedrontado por eles fica livre na área.\nEfeito Extra (um): Coragem (imune a Amedrontado); Escuridão; Luz do Dia; Descanso Pacífico (corpos não viram Mortos-Vivos); Interferência Extradimensional (sem teleporte); Medo (Amedrontado); Resistência a um tipo de dano; Silêncio; Idiomas (todos se entendem); Vulnerabilidade a um tipo de dano. Os efeitos escolhidos valem para os tipos de criatura que você definir.",
 "hold_monster": "Uma criatura que você vê no alcance faz salvaguarda de Sabedoria ou fica Paralisada pela duração, repetindo no fim de cada turno dela." + T(5),
 "insect_plague": "Gafanhotos enchem uma Esfera de 6 m de raio num ponto no alcance pela duração: Levemente Obscurecida e Terreno Difícil. Ao surgir, cada criatura nela faz salvaguarda de Constituição: 4d10 de dano Perfurante na falha, metade no sucesso; também ao entrar pela primeira vez no turno ou terminar o turno nela (uma vez por turno)." + D("1d10", 5),
 "legend_lore": "Nomeie ou descreva uma pessoa, lugar ou objeto famoso: você recebe um resumo do conhecimento importante sobre ele, dado pelo Mestre, talvez em linguagem figurada. Quanto mais já souber, mais preciso. Se não for famoso de verdade, você ouve notas tristes de trombone e a magia falha.",
 "mass_cure_wounds": "Uma onda de cura parte de um ponto que você vê no alcance. Até seis criaturas numa Esfera de 9 m de raio recuperam PV iguais a 5d8 + seu modificador de conjuração." + H("1d8", 5),
 "mislead": "Você fica Invisível e uma cópia ilusória sua surge onde está, pela duração; a invisibilidade termina se você atacar, causar dano ou conjurar. Com a ação Magia, mova a cópia até o dobro do seu Deslocamento e faça-a gesticular e falar. Ela é intangível e invulnerável, e você vê e ouve por ela.",
 "modify_memory": "Uma criatura que você vê no alcance faz salvaguarda de Sabedoria (com Vantagem se estiverem lutando). Na falha, fica Enfeitiçada e Incapacitada, alheia ao redor, mas te ouvindo; termina se sofrer dano ou for alvo de outra magia. Enquanto durar, altere a lembrança de um evento das últimas 24 horas com até 10 minutos: apagar, lembrar com clareza, mudar detalhes ou criar outro evento. Você descreve em voz alta num idioma que ela entenda; se a magia acabar antes, nada muda. Lembranças ilógicas viram sonho ruim. Remover Maldição ou Restauração Maior restauram a memória." + X("Altera eventos de até 7 dias (nível 6), 30 dias (7), 365 dias (8) ou qualquer momento do passado (9)."),
 "passwall": "Uma passagem surge num ponto que você vê numa superfície de madeira, gesso ou pedra no alcance, pela duração: até 1,5 m de largura, 2,4 m de altura e 6 m de profundidade, sem abalar a estrutura. Ao sumir, quem estiver dentro é expelido em segurança para o espaço livre mais próximo da superfície.",
 "planar_binding": "Você tenta prender ao seu serviço um Celestial, Elemental, Fada ou Corruptor que fique no alcance durante toda a conjuração (normalmente preso num Círculo Mágico invertido). Ele faz salvaguarda de Carisma ou fica vinculado pela duração (se foi invocado por magia, ela dura o mesmo). Segue suas ordens como puder; se for Hostil, tenta distorcê-las. Ao cumprir tudo, vem relatar se estiver no mesmo plano." + X("A duração aumenta com espaço de nível 6 (10 dias), 7 (30 dias), 8 (180 dias) e 9 (366 dias)."),
 "raise_dead": "Com um toque, você revive uma criatura morta há no máximo 10 dias que não era Morto-Vivo. Ela volta com 1 PV, venenos são neutralizados e ferimentos mortais se fecham, mas partes perdidas não voltam (sem partes vitais, como a cabeça, falha). Ela tem −4 em Testes de d20, reduzido em 1 a cada Descanso Longo.",
 "reincarnate": "Você toca um Humanoide morto há no máximo 10 dias (ou parte dele). Um corpo novo se forma e a alma entra nele. Role 1d10 para a espécie: 1 Aasimar, 2 Draconato, 3 Anão, 4 Elfo, 5 Gnomo, 6 Golias, 7 Halfling, 8 Humano, 9 Orc, 10 Tiferino (ou o Mestre escolhe). A criatura lembra da vida anterior e mantém suas capacidades, trocando os traços da espécie antiga pelos da nova.",
 "scrying": "Você vê e ouve uma criatura no mesmo plano. Ela faz salvaguarda de Sabedoria, modificada pelo quanto você a conhece (de segunda mão +5, já a encontrou +0, conhece bem −5) e pela ligação física (retrato −2, pertence ou roupa −4, parte do corpo ou mecha de cabelo −10). Ela só sente inquietação. No sucesso, não pode ser alvo por 24 horas. Na falha, surge um sensor Invisível a até 3 m dela que a acompanha e pelo qual você vê e ouve. Ou escolha um lugar que já viu: o sensor fica fixo lá.",
 "seeming": "Você dá uma aparência ilusória a cada criatura à sua escolha que vê no alcance (relutantes fazem salvaguarda de Carisma). Corpo e equipamento mudam, até 30 cm mais baixo ou alto, mais pesado ou leve, mantendo a disposição dos membros. Não resiste a inspeção física; com a ação Estudar e Inteligência (Investigação) contra sua CD, percebe-se o disfarce.",
 "summon_dragon": "Você invoca um espírito Dragão num espaço que você vê no alcance. Some a 0 PV ou ao fim da magia. É aliado, age logo após você na sua Iniciativa e obedece suas ordens verbais; sem ordens, usa Esquivar.\n\nEspírito Dracônico: Dragão Grande; CA 14 + nível da magia; PV 50 + 10 por nível acima de 5; Deslocamento 9 m, Voo 18 m, Natação 9 m; Resistência a Ácido, Frio, Fogo, Elétrico e Veneno; imune a Enfeitiçado, Amedrontado e Envenenado; Percepção às Cegas 9 m, Visão no Escuro 18 m." + X("Use o nível do espaço como nível da magia nas estatísticas."),
 "telekinesis": "Ao conjurar e com a ação Magia depois, você move pela mente uma criatura ou objeto que vê no alcance (trocar de alvo libera o anterior):\n\nCriatura. Enorme ou menor faz salvaguarda de Força ou é movida até 9 m em qualquer direção, ficando Impedida até o fim do seu próximo turno (suspensa, se erguida; cai depois, salvo novo uso).\nObjeto. Enorme ou menor: solto, move-se até 9 m automaticamente; se alguém o segura, essa criatura faz salvaguarda de Força ou o perde. Você também manipula com precisão (ferramentas, portas, recipientes, frascos).",
 "telepathic_bond": "Você cria um elo telepático entre até oito criaturas voluntárias no alcance, pela duração. Elas se comunicam por telepatia a qualquer distância no mesmo plano, mesmo sem idioma comum (quem não se comunica por idioma algum não é afetado).",
 "teleportation_circle": "Você desenha um círculo de 1,5 m de raio com sigilos ligados a um círculo de teletransporte permanente que conhece no mesmo plano. Um portal se abre até o fim do seu próximo turno; quem entrar aparece a até 1,5 m do círculo de destino. Templos, guildas e lugares importantes costumam ter círculos permanentes, cada um com uma sequência única de sigilos. Você começa sabendo duas (escolha do Mestre) e memoriza uma nova estudando-a por 1 minuto. Conjurar no mesmo lugar por 365 dias cria um círculo permanente.",
 "tree_stride": "Você pode entrar numa árvore viva (do seu tamanho ou maior) gastando 1,5 m de movimento e sair de outra da mesma espécie a até 150 m, surgindo a até 1,5 m dela (mais 1,5 m de movimento). Você sabe onde estão todas as árvores da espécie nesse raio. Uma vez por turno, e você precisa terminar o turno fora da árvore.",
 "wall_of_force": "Uma muralha de energia Invisível surge num ponto no alcance, em qualquer orientação: domo ou globo de até 3 m de raio, ou superfície de dez painéis contíguos de 3 × 3 m, com 6 mm de espessura, pela duração. Criaturas no caminho são empurradas para um lado (você escolhe). Nada a atravessa fisicamente; é imune a dano e a Dissipar Magia (Desintegrar a destrói) e bloqueia viagem etérea.",
 "wall_of_stone": "Uma muralha não mágica de pedra sólida surge num ponto no alcance: dez painéis contíguos de 3 × 3 m com 15 cm de espessura (ou 3 × 6 m com 7,5 cm). Criaturas no caminho são empurradas para um lado; quem ficaria cercado faz salvaguarda de Destreza e, no sucesso, usa a Reação para sair. Precisa se apoiar em pedra existente; pode formar pontes e rampas (vãos acima de 6 m exigem painéis pela metade). Cada painel tem CA 15 e 30 PV por 2,5 cm de espessura, imune a Veneno e Psíquico. Mantida a Concentração pela duração inteira, fica permanente.",
}
